1	#!/bin/bash
2	fail=0
3	t=$(mktemp); printf '# h
aoi	2026-01-01	10:00	11:00	x
kaede	2026-01-01	09:00	10:00	y
' > "$t"
4	[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
5	[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
6	[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
7	rm -f "$t"; exit $fail
